solution.solution.cpp:
#include <memory>
#include <string>
#include <vector>

struct Texture
{
    std::string name{};
};

struct Sprite
{
    std::shared_ptr<Texture> texture{};
};

std::vector<Sprite> makeSprites(const std::string& textureName, int count)
{
    const auto texture{ std::make_shared<Texture>(Texture{ textureName }) };
    std::vector<Sprite> sprites{};
    for (int i{ 0 }; i < count; ++i)
    {
        sprites.push_back(Sprite{ texture });
    }
    return sprites;
}

unitTests:
TEST("all sprites share one texture") { const auto s{ makeSprites("grass", 4) }; CHECK_EQ(s.size(), 4u); CHECK(s[0].texture != nullptr); CHECK(s[0].texture == s[3].texture); CHECK_EQ(s[1].texture->name, "grass"); }
TEST("the owner count matches the number of sprites") { auto s{ makeSprites("stone", 3) }; CHECK_EQ(s[0].texture.use_count(), 3); s.pop_back(); CHECK_EQ(s[0].texture.use_count(), 2); }
TEST("the texture outlives the sprites that are dropped") { std::shared_ptr<Texture> keep; { auto s{ makeSprites("sky", 2) }; keep = s[0].texture; } CHECK_EQ(keep.use_count(), 1); CHECK_EQ(keep->name, "sky"); }

